import{_ as a,o,c as t,a2 as n}from"./chunks/framework.Ck6QqhZl.js";const f=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"docs/installation.md","filePath":"docs/installation.md"}'),d={name:"docs/installation.md"};function i(s,e,l,r,c,h){return o(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><h2 id="forge-on-itch-io" tabindex="-1">Forge on itch.io <a class="header-anchor" href="#forge-on-itch-io" aria-label="Permalink to &quot;Forge on itch.io&quot;">​</a></h2><p>Forge is the desktop app that edits, previews, bakes, and shares <code>.soundef</code> files.</p><ul><li><strong>Download</strong> the latest build for Windows, macOS, or Linux on <strong>itch.io</strong>.</li><li>Open Forge, then <code>File → Open Project…</code> and pick your project folder (any name) that holds <code>sounds/</code> and <code>soundefs/</code> side by side. See <a href="./getting-started">Getting Started</a> for the full edit → preview → bake loop.</li></ul><p>Forge never copies or owns your audio. It reads <code>sounds/*</code> in place and writes only to <code>soundefs/*</code> (on Save) and <code>baked/*</code> (on Bake).</p><h2 id="the-format-no-install-needed" tabindex="-1">The format: no install needed <a class="header-anchor" href="#the-format-no-install-needed" aria-label="Permalink to &quot;The format: no install needed&quot;">​</a></h2><p>A <code>.soundef</code> file is plain YAML 1.2. JSON is valid too, validated against the canonical schema. There is no library to install.</p><ul><li><p><strong>Schema (canonical):</strong> served directly by this site at <a href="/soundef-site/schemas/soundef.v0.json"><code>/schemas/soundef.v0.json</code></a>. Use it to validate in any language.</p></li><li><p><strong>Two paths for your game:</strong></p><ol><li><p><strong>No runtime: bake to <code>wav</code>.</strong> In Forge, <code>Bake</code> renders a <code>.soundef</code> plus <code>seed</code> to <code>baked/&lt;name&gt;_baked_&lt;seed&gt;.wav</code>. Ship the <code>wav</code>. No code needed. See <a href="./getting-started#bake--download--share">Getting Started: Bake + Download + Share</a>.</p></li><li><p><strong>Live variation: implement the spec.</strong> Parse the YAML/JSON, validate it against the schema, then resolve a <code>PlaybackPlan</code> per <a href="./spec">Spec</a> and <a href="./integration">Integration</a>. Any engine (Godot, Unity, Unreal, Bevy, web) can do this. Or pre-resolve at build time: in Forge check <code>includes json plan</code> and <code>Bake</code> to write <code>baked/&lt;name&gt;_&lt;seed&gt;.plan.json</code> (validated at <a href="/soundef-site/schemas/playback-plan.v0.json">/schemas/playback-plan.v0.json</a>) and ship that JSON.</p></li></ol></li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./getting-started">Getting Started</a> - open a project and run the loop.</li><li><a href="./spec">Spec</a> - the file reference for every key, unit, and value form.</li><li><a href="./integration">Integration</a> - map a <code>PlaybackPlan</code> to audio and match Forge&#39;s determinism.</li><li><a href="./examples">Examples</a> - runnable project skeleton (<code>examples/demo-project/</code> with <code>sounds/</code> + <code>soundefs/</code> + <code>baked/</code>) that covers every feature.</li></ul>',10)])])}const u=a(d,[["render",i]]);export{f as __pageData,u as default};
